const app = require('./app');

describe('Health Endpoint', () => {
  test('GET /health should return status ok', async () => {
    const response = await request(app).get('/health');
    expect(response.status).toBe(200);
    expect(response.body.status).toBe('ok');
  });
});

describe('Users Endpoint', () => {
  test('GET /users should return users list', async () => {
    const response = await request(app).get('/users');
    expect(response.status).toBe(200);
    expect(response.body.status).toBe('success');
    expect(Array.isArray(response.body.data.users)).toBe(true);
  });

  test('GET /users with invalid page should return 400', async () => {
    const response = await request(app).get('/users?page=-1');
    expect(response.status).toBe(400);
    expect(response.body.status).toBe('fail');
  });

  test('GET /users with invalid limit should return 400', async () => {
    const response = await request(app).get('/users?limit=200');
    expect(response.status).toBe(400);
    expect(response.body.status).toBe('fail');
  });
});

describe('Error Handling', () => {
  test('Non-existent route should return 404', async () => {
    const response = await request(app).get('/nonexistent');
    expect(response.status).toBe(404);
    expect(response.body.status).toBe('fail');
  });
});

