/**
 * Safe Connectivity Test Template
 * 
 * This file demonstrates how to test service connectivity 
 * WITHOUT using sensitive credentials from .env.test
 */

/**
 * Example: Testing database connectivity with environment override
 * 
 * INSTRUCTIONS FOR SAFE USE:
 * 1. DO NOT use credentials from .env.test
 * 2. Set up your own test database or use local development services
 * 3. Override environment variables in YOUR local environment only
 * 
 * Example safe usage:
 *   DATABASE_URL=postgres://localhost:5432/testdb node safe-connectivity-test.js
 */

const { Pool } = require('pg');

// SAFE APPROACH: Only attempt connection if explicitly configured for testing
async function testDatabaseConnection() {
  const databaseUrl = process.env.DATABASE_URL;

  // Safety check: Only proceed if we're explicitly using a test/local database
  if (!databaseUrl) {
    console.log('✓ No database URL configured - skipping database test (SAFE)');
    return true;
  }

  // Additional safety: Check if this looks like a legitimate test database
  const isTestDatabase = 
    databaseUrl.includes('localhost') || 
    databaseUrl.includes('127.0.0.1') ||
    databaseUrl.includes('test') ||
    process.env.NODE_ENV === 'test';

  if (!isTestDatabase) {
    console.log('⚠️  Database URL does not appear to be a test database - skipping for safety');
    console.log('   To test with this database, explicitly set NODE_ENV=test and verify it\'s safe');
    return true; // Still return true to avoid blocking execution
  }

  try {
    console.log('🔌 Testing database connection...');
    const pool = new Pool({ connectionString: databaseUrl });
    const client = await pool.connect();
    await client.query('SELECT 1');
    client.release();
    await pool.end();
    console.log('✓ Database connection successful');
    return true;
  } catch (error) {
    console.error('✗ Database connection failed:', error.message);
    return false;
  }
}

/**
 * Example: Testing API connectivity with mock services
 * 
 * For external APIs, use:
 * 1. Official sandbox/test environments
 * 2. Mocking services like WireMock, MockServer, or Nock
 * 3. Environment-specific test keys (never production keys)
 */
async function testApiConnectivity() {
  // Example using a public, safe API for demonstration
  const testApiUrl = 'https://httpbin.org/status/200';

  try {
    console.log('🔌 Testing API connectivity (using safe public endpoint)...');
    const response = await fetch(testApiUrl);

    if (response.ok) {
      console.log('✓ API connectivity test successful');
      return true;
    } else {
      console.error(`✗ API test failed with status: ${response.status}`);
      return false;
    }
  } catch (error) {
    console.error('✗ API connectivity test failed:', error.message);
    return false;
  }
}

// Main test runner with safety checks
async function runConnectivityTests() {
  console.log('🧪 Running Safe Connectivity Tests\n');

  const tests = [
    testDatabaseConnection(),
    testApiConnectivity()
  ];

  const results = await Promise.all(tests);
  const allPassed = results.every(result => result === true);

  console.log(`\n🏁 Tests completed: ${allPassed ? '✅ All passed' : '❌ Some failed'}`);
  return allPassed;
}

// Only run if this file is executed directly (not imported)
if (require.main === module) {
  runConnectivityTests()
    .then(success => process.exit(success ? 0 : 1))
    .catch(err => {
      console.error('💥 Unexpected error during testing:', err);
      process.exit(1);
    });
}

module.exports = { testDatabaseConnection, testApiConnectivity };

