const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const app = express();

// Security middleware
app.use(helmet()); // Set security HTTP headers
app.use(express.json({ limit: '10kb' })); // Limit JSON body size
app.use(xss()); // Sanitize user input against XSS
app.use(mongoSanitize()); // Prevent NoSQL injection
app.use(hpp()); // Prevent parameter pollution

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again after 15 minutes'
});
app.use(limiter);

// Health check endpoint with error handling
app.get('/health', (req, res, next) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    next(error); // Pass to error handler
  }
});

// Users endpoint with input validation (for demonstration)
app.get('/users', (req, res, next) => {
  try {
    // Validate query parameters if any were expected
    // For example, if we had pagination:
    // const { page, limit } = req.query;
    // if (page && isNaN(Number(page))) {
    //   return res.status(400).json({ error: 'Page must be a number' });
    // }

    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' }
    ]);
  } catch (error) {
    next(error); // Pass to error handler
  }
});

// 404 handler for undefined routes
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.originalUrl}`
  });
});

// Centralized error handling middleware
app.use((error, req, res, next) => {
  // Log error for debugging (in production, use proper logging)
  console.error(`[${new Date().toISOString()}] Error:`, error);

  // Determine status code
  const statusCode = error.statusCode || 500;

  // Prepare error response
  const errorResponse = {
    error: {
      message: process.env.NODE_ENV === 'production' && statusCode === 500 
        ? 'Internal Server Error' 
        : error.message || 'Unknown error',
      ...(process.env.NODE_ENV !== 'production' && { stack: error.stack })
    }
  };

  // Add validation error details if applicable
  if (error.name === 'ValidationError') {
    errorResponse.error.details = error.details;
  }

  res.status(statusCode).json(errorResponse);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Application specific logging, throwing an error, or other logic here
});

