// Test script to verify connectivity of credentials in .env.test
// NOTE: This script is designed to be safe and only check basic connectivity
// without making harmful or disruptive requests

require('dotenv').config();
const https = require('https');
const { Client } = require('pg');

// Load environment variables from .env.test
const fs = require('fs');
const path = require('path');

// Simple dotenv parser for .env.test
function loadEnvFile(filePath) {
  const envVars = {};
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    content.split('\n').forEach(line => {
      line = line.trim();
      if (line && !line.startsWith('#') && line.includes('=')) {
        const [key, ...valueParts] = line.split('=');
        const value = valueParts.join('=');
        envVars[key.trim()] = value.replace(/^['"]|['"]$/g, ''); // Remove quotes
      }
    });
  } catch (error) {
    console.error(`Error reading ${filePath}:`, error.message);
  }
  return envVars;
}

// Load .env.test
const envVars = loadEnvFile(path.resolve('./.env.test'));

// Apply to process.env for consistency
Object.keys(envVars).forEach(key => {
  if (!process.env[key]) {
    process.env[key] = envVars[key];
  }
});

console.log('Testing credentials from .env.test...');
console.log('====================================');

async function testDatabaseConnection() {
  console.log('\n1. Testing Database Connection...');
  const dbUrl = process.env.DATABASE_URL;

  if (!dbUrl) {
    console.log('   ❌ DATABASE_URL not found');
    return false;
  }

  // Mask password in URL for logging
  const maskedUrl = dbUrl.replace(/:([^:@]+)@/, ':****@');
  console.log(`   Connecting to: ${maskedUrl}`);

  try {
    // Parse the connection string
    const client = new Client({ connectionString: dbUrl });

    // Set a timeout for the connection attempt
    const timeoutPromise = new Promise((_, reject) => {
      setTimeout(() => reject(new Error('Connection timeout')), 5000);
    });

    const connectPromise = client.connect();

    await Promise.race([connectPromise, timeoutPromise]);

    // If we get here, connection succeeded
    await client.query('SELECT 1');
    await client.end();
    console.log('   ✅ Database connection successful');
    return true;
  } catch (error) {
    console.log(`   ❌ Database connection failed: ${error.message}`);
    return false;
  }
}

function testHttpEndpoint(url, serviceName, headers = {}) {
  console.log(`\n2. Testing ${serviceName} endpoint...`);

  if (!url) {
    console.log(`   ❌ ${serviceName} URL not provided`);
    return false;
  }

  try {
    // For security reasons, we'll only test well-known public endpoints
    // or make minimal requests to avoid abuse
    const parsedUrl = new URL(url);

    // Only allow testing of certain domains for safety
    const allowedDomains = [
      'httpbin.org', 
      'postman-echo.com',
      'api.github.com',
      'api.stripe.com',
      'api.anthropic.com',
      'logscape-us.api.logfire.dev' // Example Logfire domain
    ];

    const isAllowed = allowedDomains.some(domain => 
      parsedUrl.hostname.endsWith(domain) || 
      parsedUrl.hostname === domain
    );

    if (!isAllowed && !url.startsWith('http://localhost') && !url.startsWith('https://localhost')) {
      console.log(`   ⚠️  Skipping ${serviceName} test - domain not in allowed list for safety`);
      console.log(`      URL: ${url}`);
      return null; // Skip test
    }

    // Make a simple GET request
    return new Promise((resolve) => {
      const reqOptions = {
        method: 'GET',
        timeout: 5000,
        headers: {
          'User-Agent': 'credential-validator/1.0',
          ...headers
        }
      };

      const req = https.request(parsedUrl, reqOptions, (res) => {
        let data = '';
        res.on('data', chunk => data += chunk);
        res.on('end', () => {
          if (res.statusCode >= 200 && res.statusCode < 400) {
            console.log(`   ✅ ${serviceName} endpoint reachable (status: ${res.statusCode})`);
            resolve(true);
          } else {
            console.log(`   ⚠️  ${serviceName} returned status: ${res.statusCode}`);
            resolve(false);
          }
        });
      });

      req.on('error', (error) => {
        console.log(`   ❌ ${serviceName} connection failed: ${error.message}`);
        resolve(false);
      });

      req.on('timeout', () => {
        req.destroy();
        console.log(`   ❌ ${serviceName} request timed out`);
        resolve(false);
      });

      req.end();
    });
  } catch (error) {
    console.log(`   ❌ Error testing ${serviceName}: ${error.message}`);
    return false;
  }
}

