// Improved Express application with error handling, input validation, and security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const cors = require('cors');
const logger = require('morgan');
const { validateUserInput } = require('./middleware/validation'); // Assuming validation middleware exists

const app = express();

// Security middleware
app.use(helmet()); // Security headers
app.use(cors()); // CORS protection
app.use(logger('combined')); // Request logging
app.use(express.json({ limit: '10kb' })); // Body parsing with size limit
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
app.use(xss()); // XSS protection
app.use(mongoSanitize()); // MongoDB injection protection
app.use(hpp()); // HTTP parameter pollution protection

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({
      status: 'error',
      message: 'Health check failed',
      error: process.env.NODE_ENV === 'development' ? error.message : undefined
    });
  }
});

// Users endpoint with validation
app.get('/users', validateUserInput, (req, res) => {
  try {
    // In a real application, this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' }
    ];

    // Add pagination and filtering based on validated query params
    const { limit, offset } = req.query;
    const paginatedUsers = users.slice(
      parseInt(offset) || 0, 
      (parseInt(offset) || 0) + (parseInt(limit) || users.length)
    );

    res.json({
      status: 'success',
      count: paginatedUsers.length,
      data: paginatedUsers
    });
  } catch (error) {
    res.status(500).json({
      status: 'error',
      message: 'Failed to retrieve users',
      error: process.env.NODE_ENV === 'development' ? error.message : undefined
    });
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: `Route ${req.originalUrl} not found`
  });
});

// Global error handling middleware
app.use((error, req, res, next) => {
  console.error(`[${new Date().toISOString()}] Error:`, error);

  // Default error status
  const statusCode = error.statusCode || 500;

  res.status(statusCode).json({
    status: 'error',
    message: error.message || 'Internal Server Error',
    // Only include stack trace in development
    stack: process.env.NODE_ENV === 'development' ? error.stack : undefined
  });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Application specific logging, throwing an error, or other logic here
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

