// Improved application with error handling, input validation, and security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { validate } = require('express-validation');
const Joi = require('joi');

const app = express();

// Security middleware
app.use(helmet());
app.use(express.json());

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all requests
app.use(limiter);

// Validation schemas
const healthCheckSchema = {
  query: Joi.object({
    // Allow optional detailed parameter for health check
    detailed: Joi.boolean().optional()
  })
};

const usersQuerySchema = {
  query: Joi.object({
    limit: Joi.number().integer().min(1).max(100).optional().default(10),
    offset: Joi.number().integer().min(0).optional().default(0),
    sortBy: Joi.string().valid('id', 'name', 'email').optional(),
    order: Joi.string().valid('asc', 'desc').optional().default('asc')
  })
};

// Health check endpoint with validation
app.get('/health', validate(healthCheckSchema), (req, res) => {
  try {
    const { detailed } = req.query;

    const response = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    };

    if (detailed) {
      response.memoryUsage = process.memoryUsage();
      response.nodeVersion = process.version;
    }

    res.json(response);
  } catch (error) {
    // Handle unexpected errors in health check
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Internal server error during health check' 
    });
  }
});

// Users endpoint with validation and error handling
app.get('/users', validate(usersQuerySchema), (req, res) => {
  try {
    const { limit, offset, sortBy, order } = req.query;

    // Simulated user data (in real app, this would come from database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' }
    ];

    // Apply sorting
    if (sortBy) {
      users.sort((a, b) => {
        if (a[sortBy] < b[sortBy]) return order === 'desc' ? 1 : -1;
        if (a[sortBy] > b[sortBy]) return order === 'desc' ? -1 : 1;
        return 0;
      });
    }

    // Apply pagination
    const paginatedUsers = users.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        limit,
        offset,
        total: users.length,
        hasMore: offset + limit < users.length
      }
    });
  } catch (error) {
    // Handle unexpected errors
    console.error('Users endpoint error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'An unexpected error occurred while fetching users'
    });
  }
});

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Route ${req.method} ${req.path} not found`
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Global error handler:', err);

  // Handle Joi validation errors
  if (err.isJoi) {
    return res.status(400).json({
      error: 'Validation error',
      details: err.details.map(detail => detail.message)
    });
  }

  // Handle express-validation errors
  if (err.status) {
    return res.status(err.status).json({
      error: err.message || 'Validation failed',
      details: err.errors || []
    });
  }

  // Handle all other errors
  res.status(500).json({
    error: 'Internal server error',
    message: process.env.NODE_ENV === 'development' ? err.message : 'Something went wrong'
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

