const request = require('supertest');
const app = require('./app');

describe('App Validation and Error Handling', () => {
  afterAll(() => {
    // Close the server after tests
    app.listen(() => app.close());
  });

  describe('GET /health', () => {
    it('should return ok status', async () => {
      const response = await request(app).get('/health');
      expect(response.status).toBe(200);
      expect(response.body.status).toBe('ok');
    });

    it('should accept detailed parameter', async () => {
      const response = await request(app)
        .get('/health')
        .query({ detailed: true });
      expect(response.status).toBe(200);
      expect(response.body.memoryUsage).toBeDefined();
    });

    it('should reject invalid detailed parameter', async () => {
      const response = await request(app)
        .get('/health')
        .query({ detailed: 'invalid' });
      expect(response.status).toBe(400);
      expect(response.body.error).toBe('Validation error');
    });
  });

  describe('GET /users', () => {
    it('should return users with default pagination', async () => {
      const response = await request(app).get('/users');
      expect(response.status).toBe(200);
      expect(Array.isArray(response.body.data)).toBe(true);
      expect(response.body.pagination.limit).toBe(10);
      expect(response.body.pagination.offset).toBe(0);
    });

    it('should accept valid query parameters', async () => {
      const response = await request(app)
        .get('/users')
        .query({ limit: 5, offset: 0, sortBy: 'name', order: 'asc' });
      expect(response.status).toBe(200);
      expect(response.body.pagination.limit).toBe(5);
    });

    it('should reject invalid limit parameter', async () => {
      const response = await request(app)
        .get('/users')
        .query({ limit: 0 }); // Below minimum
      expect(response.status).toBe(400);
      expect(response.body.error).toBe('Validation error');
    });

    it('should reject limit that is too high', async () => {
      const response = await request(app)
        .get('/users')
        .query({ limit: 101 }); // Above maximum
      expect(response.status).toBe(400);
      expect(response.body.error).toBe('Validation error');
    });

    it('should reject invalid sortBy parameter', async () => {
      const response = await request(app)
        .get('/users')
        .query({ sortBy: 'invalidField' });
      expect(response.status).toBe(400);
      expect(response.body.error).toBe('Validation error');
    });

    it('should reject invalid order parameter', async () => {
      const response = await request(app)
        .get('/users')
        .query({ order: 'invalid' });
      expect(response.status).toBe(400);
      expect(response.body.error).toBe('Validation error');
    });
  });

  describe('404 Handling', () => {
    it('should return 404 for undefined routes', async () => {
      const response = await request(app).get('/undefined-route');
      expect(response.status).toBe(404);
      expect(response.body.error).toBe('Not found');
    });
  });

  describe('Global Error Handling', () => {
    // This would require mocking an error in a route
    // For simplicity, we're just verifying the handler exists
    it('should have error handling middleware', () => {
      // The app should have error handling middleware
      expect(app).toBeDefined();
    });
  });
});

