const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { celebrate, Joi, errors } = require('celebrate');
const app = express();

// Security middleware
app.use(helmet());
// Prevent XP-powered-by header
app.disable('x-powered-by');

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body parsing
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Health check endpoint with validation
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Users endpoint with input validation and error handling
app.get('/users', 
  celebrate({
    query: Joi.object({
      limit: Joi.number().integer().min(1).max(100).default(10),
      offset: Joi.number().integer().min(0).default(0),
      sort: Joi.string().valid('name', 'email', 'id').default('id'),
      order: Joi.string().valid('asc', 'desc').default('asc')
    })
  }),
  (req, res) => {
    try {
      // Mock users data - in real app, this would come from database
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
        { id: 3, name: 'Charlie', email: 'charlie@example.com' },
        { id: 4, name: 'Diana', email: 'diana@example.com' },
        { id: 5, name: 'Eve', email: 'eve@example.com' }
      ];

      const { limit, offset, sort, order } = req.query;

      // Sort users
      const sortedUsers = [...users].sort((a, b) => {
        if (a[sort] < b[sort]) return order === 'asc' ? -1 : 1;
        if (a[sort] > b[sort]) return order === 'asc' ? 1 : -1;
        return 0;
      });

      // Paginate
      const paginatedUsers = sortedUsers.slice(offset, offset + limit);

      res.json({
        data: paginatedUsers,
        pagination: {
          limit,
          offset,
          total: users.length,
          hasMore: offset + limit < users.length
        }
      });
    } catch (error) {
      console.error('Error in /users endpoint:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// Example POST endpoint with validation
app.post('/users',
  celebrate({
    body: Joi.object({
      name: Joi.string().min(2).max(50).required().pattern(/^[a-zA-Z\s]+$/),
      email: Joi.string().email().required(),
      age: Joi.number().integer().min(0).max(150)
    })
  }),
  (req, res) => {
    try {
      // In real application, validate against database and create user
      const { name, email, age } = req.body;

      // Mock user creation
      const newUser = {
        id: Date.now(), // Simple ID generation for demo
        name: name.trim(),
        email: email.toLowerCase().trim(),
        age: age || null
      };

      res.status(201).json({
        message: 'User created successfully',
        user: newUser
      });
    } catch (error) {
      console.error('Error creating user:', error);
      res.status(500).json({ error: 'Failed to create user' });
    }
  }
);

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    message: `Route ${req.method} ${req.path} not available`
  });
});

// Error handling middleware (must be last)
app.use(errors());
app.use((error, req, res, next) => {
  // Log error for debugging (in production, use proper logging)
  console.error(`[${new Date().toISOString()}] ${req.method} ${req.path} - ${error.message}`);

  // Determine status code
  const statusCode = error.status || 500;

  // Don't leak internal errors in production
  const message = process.env.NODE_ENV === 'production' && statusCode === 500
    ? 'Internal server error'
    : error.message || 'Internal server error';

  res.status(statusCode).json({
    error: message,
    // Include error details only in development
    ...(process.env.NODE_ENV !== 'production' && { details: error.message })
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

