const { Client } = require('pg');
const AWS = require('aws-sdk');
const axios = require('axios');

async function testDatabaseConnection() {
  console.log('Testing database connection...');

  if (!process.env.DATABASE_URL) {
    console.log('❌ DATABASE_URL not found in environment');
    return false;
  }

  try {
    const client = new Client({ connectionString: process.env.DATABASE_URL });
    await client.connect();
    const res = await client.query('SELECT version()');
    await client.end();
    console.log('✅ Database connection successful');
    console.log(`   PostgreSQL version: ${res.rows[0].version.substring(0, 50)}...`);
    return true;
  } catch (error) {
    console.log('❌ Database connection failed:', error.message);
    return false;
  }
}

async function testAWSCredentials() {
  console.log('\nTesting AWS credentials...');

  if (!process.env.AWS_ACCESS_KEY_ID || !process.env.AWS_SECRET_ACCESS_KEY) {
    console.log('❌ AWS credentials not found in environment');
    return false;
  }

  try {
    // Configure AWS SDK
    AWS.config.update({
      accessKeyId: process.env.AWS_ACCESS_KEY_ID,
      secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
      region: 'us-east-1' // Default region for testing
    });

    // Test with a simple API call (STS GetCallerIdentity)
    const sts = new AWS.STS();
    const data = await sts.getCallerIdentity({}).promise();
    console.log('✅ AWS credentials valid');
    console.log(`   Account ID: ${data.Account}`);
    console.log(`   User ID: ${data.UserId}`);
    return true;
  } catch (error) {
    console.log('❌ AWS credentials validation failed:', error.message);
    // Check if it's an authentication error
    if (error.code === 'SignatureDoesNotMatch' || 
        error.code === 'InvalidClientTokenId' ||
        error.message.includes('Signature')) {
      console.log('   This indicates invalid or expired credentials');
    }
    return false;
  }
}

