function validatePostgresURL(url) {
  if (!url) return { valid: false, reason: 'URL is missing' };

  try {
    const urlObj = new URL(url);

    // Check protocol
    if (urlObj.protocol !== 'postgres:' && urlObj.protocol !== 'postgresql:') {
      return { valid: false, reason: 'Invalid protocol (should be postgres:// or postgresql://)' };
    }

    // Check hostname
    if (!urlObj.hostname) {
      return { valid: false, reason: 'Missing hostname' };
    }

    // Check port
    const port = parseInt(urlObj.port || '5432');
    if (isNaN(port) || port < 1 || port > 65535) {
      return { valid: false, reason: 'Invalid port number' };
    }

    // Check username and password (basic check)
    if (!urlObj.username) {
