// Simple connectivity test using only built-in Node.js modules
const fs = require('fs');
const net = require('net');
const tls = require('tls');
const url = require('url');

// Load environment variables from .env.test manually since we can't use dotenv
function loadEnvFile(filePath) {
  const envVars = {};
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    content.split('\n').forEach(line => {
      line = line.trim();
      if (line && !line.startsWith('#')) {
        const [key, ...valueParts] = line.split('=');
        if (key && valueParts.length > 0) {
          envVars[key.trim()] = valueParts.join('=').trim();
        }
      }
    });
  } catch (err) {
    console.error(`Error reading ${filePath}:`, err.message);
  }
  return envVars;
}

// Test TCP connectivity to a host:port
function testTcpConnection(host, port, timeout = 5000) {
  return new Promise((resolve) => {
    const socket = new net.Socket();
    let timedOut = false;

    const timeoutId = setTimeout(() => {
      timedOut = true;
      socket.destroy();
      resolve({ success: false, error: `Connection timeout after ${timeout}ms` });
    }, timeout);

    socket.once('connect', () => {
      clearTimeout(timeoutId);
      if (!timedOut) {
        socket.end();
        resolve({ success: true });
      }
    });

    socket.once('error', (err) => {
      clearTimeout(timeoutId);
      if (!timedOut) {
        resolve({ success: false, error: err.message });
      }
    });

    socket.connect(port, host);
  });
}

// Parse PostgreSQL URL and test connection
async function testPostgreSQLConnectivity(dbUrl) {
  console.log('Testing PostgreSQL connectivity...');

