    const pgUrl = new URL(dbUrl);
    const host = pgUrl.hostname;
    const port = parseInt(pgUrl.port) || 5432;

    console.log(`  Host: ${host}`);
    console.log(`  Port: ${port}`);

    const result = await testTcpConnection(host, port, 8000);

    if (result.success) {
      console.log('✅ PostgreSQL host is reachable');
      return true;
    } else {
      console.log(`❌ PostgreSQL host unreachable: ${result.error}`);
      return false;
    }
  } catch (error) {
    console.log(`❌ Invalid PostgreSQL URL: ${error.message}`);
    return false;
  }
}

// Test generic HTTPS connectivity
async function testHttpsConnectivity(hostname, path = '/', timeout = 8000) {
  return new Promise((resolve) => {
    const options = {
      hostname: hostname,
      port: 443,
      path: path,
      method: 'GET',
      timeout: timeout,
      headers: {
        'User-Agent': 'simple-test-script'
      }
    };

    const req = tls.connect(options, () => {
      // Connected successfully
      req.end();
      clearTimeout(timeoutId);
      resolve({ success: true, statusCode: 0 }); // We don't read the response, just connection
    });

    let timedOut = false;
    const timeoutId = setTimeout(() => {
      timedOut = true;
      req.destroy();
      resolve({ success: false, error: `Connection timeout after ${timeout}ms` });
    }, timeout);

    req.on('error', (err) => {
      clearTimeout(timeoutId);
      if (!timedOut) {
        resolve({ success: false, error: err.message });
      }
    });

    req.on('timeout', () => {
      clearTimeout(timeoutId);
      if (!timedOut) {
        timedOut = true;
        resolve({ success: false, error: 'Request timeout' });
      }
    });
  });
}

