// Validate the format of credentials without making network connections
const fs = require('fs');

// Load environment variables from .env.test
function loadEnvFile(filePath) {
  const envVars = {};
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    content.split('\n').forEach(line => {
      line = line.trim();
      if (line && !line.startsWith('#')) {
        const [key, ...valueParts] = line.split('=');
        if (key && valueParts.length > 0) {
          envVars[key.trim()] = valueParts.join('=').trim();
        }
      }
    });
  } catch (err) {
    console.error(`Error reading ${filePath}:`, err.message);
  }
  return envVars;
}

// Validate PostgreSQL connection string format
function validatePostgreSQLURL(url) {
  try {
    // Basic format check
    if (!url.startsWith('postgres://') && !url.startsWith('postgresql://')) {
      return { valid: false, reason: 'Must start with postgres:// or postgresql://' };
    }

    // Try to parse as URL
    const pgUrl = new URL(url);

    // Check required components
    if (!pgUrl.hostname) return { valid: false, reason: 'Missing hostname' };
    if (!pgUrl.pathname || pgUrl.pathname === '/') return { valid: false, reason: 'Missing database name' };

    // Check port if present
    if (pgUrl.port && (isNaN(pgUrl.port) || pgUrl.port < 1 || pgUrl.port > 65535)) {
      return { valid: false, reason: 'Invalid port number' };
    }

    return { valid: true };
  } catch (error) {
    return { valid: false, reason: `Invalid URL format: ${error.message}` };
  }
}

// Validate AWS Access Key ID format
function validateAWS_ACCESS_KEY_ID(key) {
  // AWS Access Key IDs are 20 characters, start with AKIA or ASIA
  if (!/^(AKIA|ASIA)[A-Z0-9]{16}$/.test(key)) {
    return { valid: false, reason: 'AWS Access Key ID should be 20 characters starting with AKIA or ASIA' };
  }
  return { valid: true };
}

// Validate AWS Secret Access Key format
function validateAWS_SECRET_ACCESS_KEY(key) {
  // AWS Secret Access Keys are 40 characters of base64-like characters
  if (!/^[A-Za-z0-9+/]{40}$/.test(key)) {
    return { valid: false, reason: 'AWS Secret Access Key should be 40 characters of base64-like characters' };
  }
  return { valid: true };
}

// Validate Anthropic API Key format
function validateANTHROPIC_API_KEY(key) {
  // Anthropic keys typically start with sk-ant- followed by alphanumeric characters
  if (!/^sk-ant-[A-Za-z0-9_-]+$/.test(key)) {
    return { valid: false, reason: 'Anthropic API key should start with sk-ant-' };
  }
  return { valid: true };
}

// Validate Stripe Secret Key format
function validateSTRIPE_SECRET_KEY(key) {
  // Stripe secret keys start with sk-live- or sk-test-
  if (!/^sk_(live|test)_ [A-Za-z0-9]{24,}$/.test(key.replace(/\s+/g, ''))) {
    return { valid: false, reason: 'Stripe secret key should start with sk-live- or sk-test-' };
  }
  return { valid: true };
}

// Validate generic token format (for Logfire and others)
function validateTOKEN_FORMAT(token, name) {
  if (!token || token.length < 10) {
    return { valid: false, reason: `${name} should be at least 10 characters long` };
  }
  return { valid: true };
}

function runFormatValidation() {
  console.log('=== Credential Format Validation ===\n');

  const envVars = loadEnvFile('./.env.test');

  if (Object.keys(envVars).length === 0) {
    console.log('❌ No environment variables found in .env.test');
    return false;
  }

  console.log('Loaded environment variables:');
  for (const [key, value] of Object.entries(envVars)) {
    if (value && value.length > 8) {
      const masked = value.substring(0, 4) + '*' .repeat(value.length - 8) + value.substring(value.length - 4);
      console.log(`  ${key}: ${masked}`);
    } else {
      console.log(`  ${key}: ${value || '(empty)'}`);
    }
  }
  console.log('');

  const validators = [
    { key: 'DATABASE_URL', func: validatePostgreSQLURL, name: 'PostgreSQL URL' },
    { key: 'AWS_ACCESS_KEY_ID', func: validateAWS_ACCESS_KEY_ID, name: 'AWS Access Key ID' },
    { key: 'AWS_SECRET_ACCESS_KEY', func: validateAWS_SECRET_ACCESS_KEY, name: 'AWS Secret Access Key' },
    { key: 'ANTHROPIC_API_KEY', func: validateANTHROPIC_API_KEY, name: 'Anthropic API Key' },
    { key: 'STRIPE_SECRET_KEY', func: validateSTRIPE_SECRET_KEY, name: 'Stripe Secret Key' },
    { key: 'LOGFIRE_TOKEN', func: (token) => validateTOKEN_FORMAT(token, 'Logfire Token'), name: 'Logfire Token' }
  ];

  let allValid = true;

  for.validator) {
    const value = envVars[validator.key];

    if (value === undefined) {
      console.log(`❌ ${validator.name}: NOT FOUND`);
      allValid = false;
      continue;
    }

    if (value === '') {
      console.log(`❌ ${validator.name}: EMPTY VALUE`);
      allValid = false;
      continue;
    }

    const result = validator.func(value);

    if (result.valid) {
      console.log(`✅ ${validator.name}: VALID format`);
    } else {
      console.log(`❌ ${validator.name}: INVALID format - ${result.reason}`);
      allValid = false;
    }
  }

  console.log(`\n=== Summary: Format validation ${allValid ? 'PASSED' : 'FAILED'} ===\n`);

  if (allValid) {
    console.log('🎉 All credentials have valid formats!');
    console.log('Note: This only validates format, not actual validity or security.');
  } else {
    console.log('⚠️  Some credentials have invalid formats.');
  }

  return allValid;
}

// Run validation
if (require.main === module) {
  const success = runFormatValidation();
  process.exit(success ? 0 : 1);
}

