// Improved application with enhanced error handling, input validation, and security practices

const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const AppError = require('./utils/appError');
const globalErrorHandler = require('./controllers/errorController');
const logger = require('./utils/logger');

const app = express();

// Security Middleware
app.use(helmet()); // Set security HTTP headers

// Limit requests from same API
const limiter = rateLimit({
  max: 100,
  windowMs: 60 * 60 * 1000, // 1 hour
  message: 'Too many requests from this IP, please try again later.'
});
app.use('/api', limiter);

// Body parser, reading data from body into req.body
app.use(express.json({ limit: '10kb' }));

// Data sanitization against XSS
app.use(xss());

// Data sanitization against NoSQL query injection
app.use(mongoSanitize());

// Prevent parameter pollution
app.use(hpp({
  whitelist: [] // Add safe parameters here if needed
}));

// Test middleware
app.use((req, res, next) => {
  req.requestTime = new Date().toISOString();
  logger.info(`${req.method} ${req.url} - ${req.ip}`);
  next();
});

// Routes
app.get('/health', (req, res) => {
  res.status(200).json({
    status: 'success',
    timestamp: req.requestTime,
    message: 'Server is healthy'
  });
});

app.get('/users', (req, res) => {
  // Input validation for query parameters
  const { limit, sort } = req.query;

  // Validate limit parameter
  let parsedLimit = 10; // Default
  if (limit !== undefined) {
    parsedLimit = parseInt(limit, 10);
    if (isNaN(parsedLimit) || parsedLimit <= 0 || parsedLimit > 100) {
      return res.status(400).json({
        status: 'fail',
        message: 'Limit must be a positive number between 1 and 100'
      });
    }
  }

  // Mock users data with pagination
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
    { id: 3, name: 'Charlie', email: 'charlie@example.com' }
  ];

  // Apply limit
  const limitedUsers = users.slice(0, parsedLimit);

  res.status(200).json({
    status: 'success',
    results: limitedUsers.length,
    data: {
      users: limitedUsers
    }
  });
});

// Handle undefined routes
app.all('*', (req, res, next) => {
  next(new AppError(`Can't find ${req.originalUrl} on this server!`, 404));
});

// Global error handling middleware
app.use(globalErrorHandler);

module.exports = app;

