// Demonstration of how the improved error handling prevents credential leakage

// This simulates what would happen if an error occurred that exposed environment variables

const AppError = require('./utils/appError');
const { sendErrorProd } = require('./controllers/errorController');

function simulateCredentialLeakAttempt() {
  console.log('🔒 Demonstrating Error Handling Security\n');

  // Simulate an error that might accidentally include sensitive data
  try {
    // Imagine some code that tries to access a database but fails
    const fakeDbError = new Error('Connection failed: password authentication failed for user "admin"');

    // In a poorly handled scenario, someone might do this:
    // return res.status(500).json({ error: fakeDbError.message, stack: fakeDbError.stack });
    // This could leak connection strings or other sensitive info in the message

    // Instead, our improved approach:
    const operationalError = new AppError('Database connection failed', 500);
    // Note: We don't include the raw error message that might contain credentials

    console.log('📝 Original error (what we caught internally):');
    console.log('   ', fakeDbError.message);
    console.log();

    console.log('📤 What we send to the client (production mode):');
    const mockRes = {
      status: function(code) {
        this.statusCode = code;
        return this;
      },
      json: function(data) {
        console.log('   Status:', this.statusCode);
        console.log('   Response:', JSON.stringify(data, null, 2));
        return this;
      }
    };

    sendErrorProd(operationalError, mockRes);
    console.log();

    console.log('✅ Security Benefit:');
    console.log('   - No connection string exposed');
    console.log('   - No partial credentials leaked');
    console.log('   - No stack trace revealing internal structure');
    console.log('   - Generic but helpful error message');

  } catch (err) {
    console.error('Unexpected error in demonstration:', err);
  }
}

function simulateDevelopmentVsProduction() {
  console.log('\n🔧 Development vs Production Error Handling\n');

  const testError = new AppError('Validation failed for input', 400);
  testError.isOperational = true;

  // Simulate development response
  console.log('🛠️  Development Response:');
  const mockResDev = {
    status: function(code) {
      this.statusCode = code;
      return this;
    },
    json: function(data) {
      console.log('   Status:', this.statusCode);
      // In development, we'd include more details
      const devResponse = {
        status: data.status,
        message: data.message,
        // These would be included in development:
        error: { message: testError.message },
        stack: testError.stack ? testError.stack.split('\n').slice(0, 2).join('\n') + '\n...' : 'No stack'
      };
      console.log('   Response:', JSON.stringify(devResponse, null, 2));
      return this;
    }
  };

  // Temporarily override NODE_ENV for demo
  const oldEnv = process.env.NODE_ENV;
  process.env.NODE_ENV = 'development';

  // We'd normally call the error handler, but for demo we'll show conceptually
  console.log('   [Would include full error details and stack trace]');

  // Simulate production response  
  console.log('\n🚢 Production Response:');
  const mockResProd = {
    status: function(code) {
      this.statusCode = code;
      return this;
    },
    json: function(data) {
      console.log('   Status:', this.statusCode);
      console.log('   Response:', JSON.stringify(data, null, 2));
      return this;
    }
  };

  process.env.NODE_ENV = 'production';
  sendErrorProd(testError, mockResProd);

  console.log();
  console.log('✅ Security Benefit:');
  console.log('   - Development: Detailed debugging info');
  console.log('   - Production: Minimal info to prevent leakage');
  console.log('   - Same underlying error, different exposure levels');

  // Restore
  process.env.NODE_ENV = oldEnv;
}

// Run demonstrations
simulateCredentialLeakAttempt();
simulateDevelopmentVsProduction();

console.log('\n🎯 Key Takeaway:');
console.log('   Good error handling is a critical security control');
console.log('   that prevents accidental sensitive data exposure');
console.log('   while maintaining necessary debugging capabilities.');

