## Security and Error Handling Review of app.js

After reviewing the app.js file, I've identified several areas for improvement regarding error handling, input validation, and security best practices:

### Current Issues:

1. **No Input Validation**: The `/users` endpoint accepts query parameters but doesn't validate them
2. **Minimal Error Handling**: No try/catch blocks or error handling middleware
3. **Security Headers Missing**: No security headers like Helmet
4. **Rate Limiting Missing**: No protection against brute force or DoS attacks
5. **No Input Sanitization**: Potential for injection attacks
6. **No Logging**: Limited debugging and monitoring capabilities
7. **No CORS Configuration**: Unrestricted cross-origin requests

### Recommended Improvements:

Here's an enhanced version of app.js with better security practices:

```javascript
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const cors = require('cors');
const AppError = require('./utils/appError');
const globalErrorHandler = require('./controllers/errorController');

const app = express();

// Security Middleware
app.use(helmet()); // Set security HTTP headers
app.use(cors()); // Enable CORS with origin whitelist in production

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  max: 100, // limit each IP to 100 requests per windowMs
  windowMs: 60 * 60 * 1000, // 1 hour
  message: 'Too many requests from this IP, please try again in an hour!'
});
app.use('/api', limiter);

// Body parser, reading data from body into req.body
app.use(express.json({ limit: '10kb' }));

// Data sanitization against XSS
app.use(xss());

// Data sanitization against NoSQL query injection
app.use(mongoSanitize());

// Prevent parameter pollution
app.use(hpp({
  whitelist: ['duration'] // allow duplicate parameters in whitelist array
}));

// Routes
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res, next) => {
  try {
    // Input validation and sanitization
    const { limit, offset, search } = req.query;

    // Validate limit and offset are numbers
    if (limit !== undefined && (isNaN(parseInt(limit)) || parseInt(limit) < 0)) {
      return next(new AppError('Limit must be a positive number', 400));
    }

    if (offset !== undefined && (isNaN(parseInt(offset)) || parseInt(offset) < 0)) {
      return next(new AppError('Offset must be a non-negative number', 400));
    }

    // Sanitize search input (if using in database query)
    const sanitizedSearch = search ? search.trim().substring(0, 100) : ''; // Limit length

    // Mock user data with filtering
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' }
    ];

    // Apply search filter if provided
    if (sanitizedSearch) {
      const searchLower = sanitizedSearch.toLowerCase();
      users = users.filter(user => 
        user.name.toLowerCase().includes(searchLower) || 
        user.email.toLowerCase().includes(searchLower)
      );
    }

