// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Input validation schemas
const userQuerySchema = {
  query: Joi.object({
    limit: Joi.number().integer().min(1).max(100).default(10),
    offset: Joi.number().integer().min(0).default(0),
    sort: Joi.string().valid('name', 'email', 'id').default('id'),
    order: Joi.string().valid('asc', 'desc').default('asc')
  })
};

const userIdSchema = {
  params: Joi.object({
    id: Joi.number().integer().positive.required()
  })
};

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Get users with validation
app.get('/users', validate(userQuerySchema), (req, res) => {
  try {
    const { limit, offset, sort, order } = req.query;

    // In a real app, this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' }
    ];

    // Simulate filtering and pagination
    const sortedUsers = [...users].sort((a, b) => {
      if (a[sort] < b[sort]) return order === 'asc' ? -1 : 1;
      if (a[sort] > b[sort]) return order === 'asc' ? 1 : -1;
      return 0;
    });

    const paginatedUsers = sortedUsers.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        limit,
        offset,
        total: users.length,
        hasMore: offset + limit < users.length
      }
    });
  } catch (error) {
    res.status(500).json({ error: 'Failed to retrieve users' });
  }
});

// Get specific user by ID with validation
app.get('/users/:id', validate(userIdSchema), (req, res) => {
  try {
    const { id } = req.params;

    // In a real app, this would query a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' }
    ];

    const user = users.find(u => u.id === parseInt(id));

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json({ data: user });
  } catch (error) {
    res.status(500).json({ error: 'Failed to retrieve user' });
  }
});

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Handle validation errors
  if (err.isJoi) {
    return res.status(400).json({ 
      error: 'Validation Error', 
      details: err.details 
    });
  }

  // Handle express-validation errors
  if (err.status) {
    return res.status(err.status).json({ 
      error: err.message || 'Validation Error',
      details: err.details 
    });
  }

  // Handle other errors
  res.status(500).json({ 
    error: 'Internal Server Error',
    message: process.env.NODE_ENV === 'development' ? err.message : undefined
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

