// Improved application with proper error handling and input validation
// Focus on security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const cors = require('cors');

const app = express();

// Security Middleware
app.use(helmet()); // Set security HTTP headers
app.use(cors({     // Configure CORS properly
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  credentials: true
}));
app.use(express.json({ limit: '10kb' })); // Limit JSON payload size
app.use(urlencoded({ extended: true, limit: '10kb' }));
app.use(mongoSanitize()); // Prevent NoSQL injection
app.use(xss()); // Prevent XSS attacks
app.use(hpp()); // Prevent HTTP parameter pollution

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again after 15 minutes'
  },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Health check endpoint with proper error handling
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({ 
      error: 'Internal server error',
      message: process.env.NODE_ENV === 'development' ? error.message : undefined
    });
  }
});

// Users endpoint with input validation and sanitization
app.get('/users', (req, res) => {
  try {
    // Validate and sanitize query parameters
    const page = parseInt(req.query.page) || 1;
    const limit = Math.min(parseInt(req.query.limit) || 10, 100); // Max 100 items
    const search = req.query.search ? req.query.search.trim().substring(0, 50) : ''; // Limit search length

    // Input validation
    if (isNaN(page) || page < 1) {
      return res.status(400).json({ 
        error: 'Validation failed',
        message: 'Page must be a positive integer'
      });
    }

    if (isNaN(limit) || limit < 1) {
      return res.status(400).json({ 
        error: 'Validation failed',
        message: 'Limit must be a positive integer'
      });
    }

    // Simulate database query with safe parameters
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply search filter if provided (sanitized)
    let filteredUsers = users;
    if (search) {
      const safeSearch = search.toLowerCase();
      filteredUsers = users.filter(user => 
        user.name.toLowerCase().includes(safeSearch) || 
        user.email.toLowerCase().includes(safeSearch)
      );
    }

    // Apply pagination
    const startIndex = (page - 1) * limit;
    const endIndex = startIndex + limit;
    const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

    res.json({
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: filteredUsers.length,
        totalPages: Math.ceil(filteredUsers.length / limit)
      }
    });

  } catch (error) {
    // Proper error handling
    console.error('Error in /users endpoint:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: process.env.NODE_ENV === 'development' ? error.message : undefined
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Route ${req.originalUrl} not found`
  });
});

// Centralized error handling middleware
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Default to 500 if no status code
  const statusCode = error.statusCode || 500;

  res.status(statusCode).json({
    error: error.message || 'Internal server error',
    ...(process.env.NODE_ENV === 'development' && { stack: error.stack })
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

