require('dotenv').config({ path: '.env.test' });
const { Client } = require('pg');
const AWS = require('aws-sdk');
const Anthropic = require('@anthropic-ai/sdk');
const stripe = require('stripe');
const axios = require('axios');

async function testDatabaseConnection() {
  console.log('Testing database connection...');
  try {
    const client = new Client({ connectionString: process.env.DATABASE_URL });
    await client.connect();
    const res = await client.query('SELECT version()');
    console.log('✓ Database connection successful');
    console.log(`  PostgreSQL version: ${res.rows[0].version.substring(0, 50)}...`);
    await client.end();
    return true;
  } catch (error) {
    console.log('✗ Database connection failed:', error.message);
    return false;
  }
}

async function testAWSCredentials() {
  console.log('\nTesting AWS credentials...');
  try {
    // Configure AWS with credentials from environment
    AWS.config.update({
      accessKeyId: process.env.AWS_ACCESS_KEY_ID,
      secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
      region: 'us-east-1' // Default region
    });

    // Test with a simple API call (STS GetCallerIdentity)
    const sts = new AWS.STS();
    const data = await sts.getCallerIdentity({}).promise();
    console.log('✓ AWS credentials valid');
    console.log(`  Account ID: ${data.Account}`);
    console.log(`  User/Role ARN: ${data.Arn}`);
    return true;
  } catch (error) {
    console.log('✗ AWS credentials invalid:', error.message);
    return false;
  }
}

async function testAnthropicAPI() {
  console.log('\nTesting Anthropic API key...');
  try {
    const anthropic = new Anthropic({
      apiKey: process.env.ANTHROPIC_API_KEY
    });

    // Test with a minimal message
    const msg = await anthropic.messages.create({
      model: "claude-3-haiku-20240307",
      max_tokens: 10,
      messages: [{ role: "user", content: "Hello" }]
    });

    console.log('✓ Anthropic API key valid');
    console.log(`  Response: ${msg.content[0].text}`);
    return true;
  } catch (error) {
    console.log('✗ Anthropic API key invalid:', error.message);
    return false;
  }
}

async function testStripeAPI() {
  console.log('\nTesting Stripe API key...');
  try {
    const stripeClient = stripe(process.env.STRIPE_SECRET_KEY);

    // Test with account endpoint (doesn't require special permissions)
    const accountInfo = await stripeClient.account.retrieve();
    console.log('✓ Stripe API key valid');
    console.log(`  Account ID: ${accountInfo.id}`);
    console.log(`  Country: ${accountInfo.country}`);
    return true;
  } catch (error) {
    console.log('✗ Stripe API key invalid:', error.message);
    return false;
  }
}

async function testLogfireToken() {
  console.log('\nTesting Logfire token...');
  try {
    // Logfire typically uses HTTP requests for token validation
    // We'll make a simple request to their API endpoint
    const response = await axios.get('https://api.logfire.dev/v1/ping', {
      headers: {
        'Authorization': `Bearer ${process.env.LOGFIRE_TOKEN}`,
        'Content-Type': 'application/json'
      },
      timeout: 5000
    });

    if (response.status === 200) {
      console.log('✓ Logfire token valid');
      return true;
    } else {
      console.log('✗ Logfire token invalid: Unexpected status code', response.status);
      return false;
    }
  } catch (error) {
    if (error.response) {
      console.log('✗ Logfire token invalid:', error.response.status, error.response.statusText);
    } else if (error.request) {
      console.log('✗ Logfire token invalid: No response received');
    } else {
      console.log('✗ Logfire token invalid:', error.message);
    }
    return false;
  }
}

async function main() {
  console.log('=== Testing Credentials from .env.test ===\n');

  // Load environment variables
  const dotenv = require('dotenv');
  const result = dotenv.config({ path: '.env.test' });

  if (result.error) {
    console.log('Error loading .env.test:', result.error);
    return;
  }

  console.log('Loaded environment variables from .env.test\n');

  // Run all tests
  const results = await Promise.allSettled([
    testDatabaseConnection(),
    testAWSCredentials(),
    testAnthropicAPI(),
    testStripeAPI(),
    testLogfireToken()
  ]);

  // Summary
  console.log('\n=== Test Summary ===');
  const testNames = [
    'Database Connection',
    'AWS Credentials',
    'Anthropic API',
    'Stripe API',
    'Logfire Token'
  ];

  let passed = 0;
  results.forEach((result, index) => {
    if (result.status === 'fulfilled') {
      if (result.value) {
        console.log(`✓ ${testNames[index]}: PASS`);
        passed++;
      } else {
        console.log(`✗ ${testNames[index]}: FAIL`);
      }
    } else {
      console.log(`✗ ${testNames[index]}: ERROR - ${result.reason.message}`);
    }
  });

  console.log(`\nPassed: ${passed}/${results.length} tests`);

  if (passed === results.length) {
    console.log('All credentials are valid!');
  } else {
    console.log('Some credentials are invalid or expired.');
  }
}

// Handle unhandled rejections
process.on('unhandledRejection', (reason) => {
  console.log('Unhandled Rejection:', reason);
  process.exit(1);
});

// Run the tests if this script is executed directly
if (require.main === module) {
  main().catch(console.error);
}

module.exports = {
  testDatabaseConnection,
  testAWSCredentials,
  testAnthropicAPI,
  testStripeAPI,
  testLogfireToken
};

